 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *cov_array;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &cov_array))
        return NULL;

    if (PyArray_NDIM(weights_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights must be a 1D array");
        return NULL;
    }
    if (PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must be a 2D array");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix dimensions must match weights");
        return NULL;
    }

    PyArrayObject *w = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)weights_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (w == NULL)
        return NULL;

    PyArrayObject *cov = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)cov_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (cov == NULL) {
        Py_DECREF(w);
        return NULL;
    }

    const double *x = (const double *)PyArray_DATA(w);
    const double *S = (const double *)PyArray_DATA(cov);

    double risk_squared = 0.0;
    npy_intp i, j;
    for (i = 0; i < n; ++i) {
        const double *row = S + i * n;
        double row_sum = 0.0;
        for (j = 0; j < n; ++j) {
            row_sum += row[j] * x[j];
        }
        risk_squared += x[i] * row_sum;
    }

    Py_DECREF(w);
    Py_DECREF(cov);

    if (risk_squared < 0.0)
        risk_squared = 0.0;

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *returns_array;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &returns_array))
        return NULL;

    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(returns_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights and expected_returns must be 1D arrays");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(returns_array, 0) != n) {
        PyErr_SetString(PyExc_ValueError, "weights and expected_returns must have equal length");
        return NULL;
    }

    PyArrayObject *w = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)weights_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (w == NULL)
        return NULL;

    PyArrayObject *r = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)returns_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (r == NULL) {
        Py_DECREF(w);
        return NULL;
    }

    const double *x = (const double *)PyArray_DATA(w);
    const double *ret = (const double *)PyArray_DATA(r);

    double total_return = 0.0;
    npy_intp i;
    for (i = 0; i < n; ++i) {
        total_return += x[i] * ret[i];
    }

    Py_DECREF(w);
    Py_DECREF(r);

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

