/*
 * High-performance portfolio calculations using C extension
 *
 * Uses a fast path for plain Python lists (the common case) that reads the
 * data directly without first materialising a NumPy copy.  NumPy arrays and
 * other array-like inputs fall back to the NumPy C API.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static inline double seq_item_as_double(PyObject *item) {
    if (PyFloat_CheckExact(item))
        return PyFloat_AS_DOUBLE(item);
    return PyFloat_AsDouble(item);
}

/* Fast path: weights is a list/tuple, cov is a list of row sequences. */
static PyObject* risk_py_sequences(PyObject *weights, PyObject *cov) {
    Py_ssize_t n = PySequence_Size(weights);
    if (n < 0)
        return NULL;
    if (PySequence_Size(cov) != n) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix dimensions must match weights");
        return NULL;
    }

    double risk_squared = 0.0;
    Py_ssize_t i, j;
    for (i = 0; i < n; ++i) {
        PyObject *witem = PySequence_Fast_GET_ITEM(weights, i);
        double xi = seq_item_as_double(witem);
        PyObject *row = PySequence_Fast_GET_ITEM(cov, i);
        PyObject *fast_row = PySequence_Fast(row, "covariance row must be a sequence");
        if (fast_row == NULL)
            return NULL;
        Py_ssize_t row_len = PySequence_Fast_GET_SIZE(fast_row);
        if (row_len != n) {
            Py_DECREF(fast_row);
            PyErr_SetString(PyExc_ValueError, "cov_matrix dimensions must match weights");
            return NULL;
        }
        PyObject **items = PySequence_Fast_ITEMS(fast_row);
        double row_sum = 0.0;
        for (j = 0; j < n; ++j) {
            row_sum += seq_item_as_double(items[j]) * seq_item_as_double(
                PySequence_Fast_GET_ITEM(weights, j));
        }
        Py_DECREF(fast_row);
        risk_squared += xi * row_sum;
    }

    if (risk_squared < 0.0)
        risk_squared = 0.0;
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    /* Fast path only when neither input is a NumPy array. */
    if (!PyArray_Check(weights_obj) && !PyArray_Check(cov_obj) &&
        PySequence_Check(weights_obj) && PySequence_Check(cov_obj)) {
        PyObject *weights = PySequence_Fast(weights_obj, "weights must be a sequence");
        if (weights == NULL)
            return NULL;
        PyObject *cov = PySequence_Fast(cov_obj, "cov_matrix must be a sequence");
        if (cov == NULL) {
            Py_DECREF(weights);
            return NULL;
        }
        PyObject *result = risk_py_sequences(weights, cov);
        Py_DECREF(weights);
        Py_DECREF(cov);
        return result;
    }

    PyArrayObject *weights_array = (PyArrayObject *)weights_obj;
    PyArrayObject *cov_array = (PyArrayObject *)cov_obj;

    if (PyArray_NDIM(weights_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights must be a 1D array");
        return NULL;
    }
    if (PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must be a 2D array");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix dimensions must match weights");
        return NULL;
    }

    PyArrayObject *w = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)weights_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (w == NULL)
        return NULL;

    PyArrayObject *cov = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)cov_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (cov == NULL) {
        Py_DECREF(w);
        return NULL;
    }

    const double *x = (const double *)PyArray_DATA(w);
    const double *S = (const double *)PyArray_DATA(cov);

    double risk_squared = 0.0;
    npy_intp i, j;
    for (i = 0; i < n; ++i) {
        const double *row = S + i * n;
        double row_sum = 0.0;
        for (j = 0; j < n; ++j) {
            row_sum += row[j] * x[j];
        }
        risk_squared += x[i] * row_sum;
    }

    Py_DECREF(w);
    Py_DECREF(cov);

    if (risk_squared < 0.0)
        risk_squared = 0.0;

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    if (!PyArray_Check(weights_obj) && !PyArray_Check(returns_obj) &&
        PySequence_Check(weights_obj) && PySequence_Check(returns_obj)) {
        PyObject *weights = PySequence_Fast(weights_obj, "weights must be a sequence");
        if (weights == NULL)
            return NULL;
        PyObject *returns = PySequence_Fast(returns_obj, "expected_returns must be a sequence");
        if (returns == NULL) {
            Py_DECREF(weights);
            return NULL;
        }
        Py_ssize_t n = PySequence_Fast_GET_SIZE(weights);
        if (PySequence_Fast_GET_SIZE(returns) != n) {
            Py_DECREF(weights);
            Py_DECREF(returns);
            PyErr_SetString(PyExc_ValueError, "weights and expected_returns must have equal length");
            return NULL;
        }
        PyObject **witems = PySequence_Fast_ITEMS(weights);
        PyObject **ritems = PySequence_Fast_ITEMS(returns);
        double total_return = 0.0;
        Py_ssize_t i;
        for (i = 0; i < n; ++i) {
            total_return += seq_item_as_double(witems[i]) * seq_item_as_double(ritems[i]);
        }
        Py_DECREF(weights);
        Py_DECREF(returns);
        return PyFloat_FromDouble(total_return);
    }

    PyArrayObject *weights_array = (PyArrayObject *)weights_obj;
    PyArrayObject *returns_array = (PyArrayObject *)returns_obj;

    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(returns_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights and expected_returns must be 1D arrays");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(returns_array, 0) != n) {
        PyErr_SetString(PyExc_ValueError, "weights and expected_returns must have equal length");
        return NULL;
    }

    PyArrayObject *w = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)weights_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (w == NULL)
        return NULL;

    PyArrayObject *r = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)returns_array, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (r == NULL) {
        Py_DECREF(w);
        return NULL;
    }

    const double *x = (const double *)PyArray_DATA(w);
    const double *ret = (const double *)PyArray_DATA(r);

    double total_return = 0.0;
    npy_intp i;
    for (i = 0; i < n; ++i) {
        total_return += x[i] * ret[i];
    }

    Py_DECREF(w);
    Py_DECREF(r);

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
